```tsx
import { useId, useState } from "react";
import "./CodeCard.css";

export interface CodeCardProps {
  title: string;
  code: string;
  /** Called after the code has been copied to the clipboard. */
  onCopy?: (code: string) => void;
}

type CopyState = "idle" | "copied" | "failed";

export function CodeCard({ title, code, onCopy }: CodeCardProps) {
  const titleId = useId();
  const [copyState, setCopyState] = useState<CopyState>("idle");

  async function handleCopy(): Promise<void> {
    try {
      await navigator.clipboard.writeText(code);
      setCopyState("copied");
      onCopy?.(code);
    } catch {
      setCopyState("failed");
    }
  }

  return (
    <section className="code-card" aria-labelledby={titleId}>
      <header className="code-card-header">
        <h2 id={titleId} className="code-card-title">
          {title}
        </h2>
        <button type="button" className="code-card-button" onClick={handleCopy}>
          Copy
        </button>
      </header>

      <pre className="code-card-code" tabIndex={0} aria-label={`${title} SQL`}>
        <code>{code}</code>
      </pre>

      <p className="code-card-status" role="status">
        {copyState === "copied" ? "Copied to clipboard." : ""}
      </p>
      {copyState === "failed" ? (
        <p className="code-card-alert" role="alert">
          Copy failed. Select the code and copy it by hand.
        </p>
      ) : null}
    </section>
  );
}
```

